/*!
 * \file
 * \brief Defines the compiled Na-24 marginal source-emission laws.
 *
 * LNHB: V. P. Chechev and N. K. Kuzmenko, June 2014. Selected beta-minus
 * source emissions.
 *
 * BetaShape 2.4 (06/2024): experimental shape for the dominant branch;
 * calculated shapes otherwise. Conditional masses integrate the selected
 * piecewise-linear densities; full-support references and finite grids
 * remain distinct.
 *
 * Retained forbidden non-unique laws carry Xi-approximation warnings;
 * numerical agreement does not establish experimental shape accuracy.
 *
 * Physical yields remain independent emissions per parent decay. Selected
 * photon and conversion lines use absolute LNHB yields; unsupported Auger
 * energy laws are excluded.
 *
 * Selection and exclusions: validation/radioactivity/data/Na-24/reference/.
 *
 * \author Julien BERT <julien.bert@univ-brest.fr>
 * \author Didier BENOIT <didier.benoit@inserm.fr>
 */

