[[nodiscard]] auto BuildNa24Radionuclide() -> GGEMSRadionuclideDefinition {
  std::vector<GGEMSRadionuclideEmission> emissions;
  emissions.reserve(12U);

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_280_49_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_280_49_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_280_49_keV_bin_width_micro_eV,
      },
      k_beta_minus_280_49_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_1277_37_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_1277_37_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_1277_37_keV_bin_width_micro_eV,
      },
      k_beta_minus_1277_37_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_1392_721_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_1392_721_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_1392_721_keV_bin_width_micro_eV,
      },
      k_beta_minus_1392_721_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Electron, k_beta_minus_4146_938_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_minus_4146_938_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_minus_4146_938_keV_bin_width_micro_eV,
      },
      k_beta_minus_4146_938_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Gamma, k_nuclear_gamma_yield,
    sources::GGEMSEnergyDistribution::BuildDiscreteLines(
      k_nuclear_gamma_energies_micro_eV, k_nuclear_gamma_line_yields));

  emissions.emplace_back(
    particles::GGEMSParticleType::Gamma, k_atomic_xray_yield,
    sources::GGEMSEnergyDistribution::BuildDiscreteLines(
      k_atomic_xray_energies_micro_eV, k_atomic_xray_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_996_86_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_996_86_keV_energies_micro_eV,
                           k_conversion_996_86_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_1368_63_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_1368_63_keV_energies_micro_eV,
                           k_conversion_1368_63_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_2754_049_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_2754_049_keV_energies_micro_eV,
                           k_conversion_2754_049_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_2869_38_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_2869_38_keV_energies_micro_eV,
                           k_conversion_2869_38_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_3866_12_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_3866_12_keV_energies_micro_eV,
                           k_conversion_3866_12_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_4237_84_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_4237_84_keV_energies_micro_eV,
                           k_conversion_4237_84_keV_line_yields));

  return {"Na-24", k_half_life_seconds, std::move(emissions)};
}

